package serializer

import (
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

type CircuitState int

const (
	StateClosed CircuitState = iota
	StateOpen
	StateHalfOpen
)

type CircuitBreaker struct {
	mu           sync.Mutex
	state        CircuitState
	failures     int
	threshold    int
	resetTimeout time.Duration
	lastFailure  time.Time
}

func NewCircuitBreaker(threshold int, timeout time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		state:        StateClosed,
		threshold:    threshold,
		resetTimeout: timeout,
	}
}

func (cb *CircuitBreaker) Execute(fn func() error) error {
	cb.mu.Lock()
	if cb.state == StateOpen {
		if time.Since(cb.lastFailure) > cb.resetTimeout {
			cb.state = StateHalfOpen
		} else {
			cb.mu.Unlock()
			return fmt.Errorf("circuit breaker is open")
		}
	}
	cb.mu.Unlock()

	err := fn()

	cb.mu.Lock()
	defer cb.mu.Unlock()
	if err != nil {
		cb.failures++
		cb.lastFailure = time.Now()
		if cb.failures >= cb.threshold {
			cb.state = StateOpen
		}
		return err
	}
	cb.failures = 0
	cb.state = StateClosed
	return nil
}

type SerializationManifest struct {
	Version    string            `json:"version"`
	BasePath   string            `json:"base_path"`
	Fragments  []FragmentRef     `json:"fragments"`
	Metadata   map[string]string `json:"metadata"`
}

type FragmentRef struct {
	Name     string `json:"name"`
	RelPath  string `json:"rel_path"`
	Checksum string `json:"checksum"`
}

type SerializerEngine struct {
	baseDir string
	cb      *CircuitBreaker
}

func NewSerializerEngine(baseDir string) *SerializerEngine {
	return &SerializerEngine{
		baseDir: baseDir,
		cb:      NewCircuitBreaker(3, 30*time.Second),
	}
}

func (se *SerializerEngine) sanitizePath(component string) string {
	cleaned := filepath.Clean(component)
	cleaned = strings.ReplaceAll(cleaned, "..", "")
	return cleaned
}

func (se *SerializerEngine) resolveFragmentPath(manifest *SerializationManifest, fragment *FragmentRef) string {
	sanitizedBase := se.sanitizePath(manifest.BasePath)
	sanitizedRel := se.sanitizePath(fragment.RelPath)

	// Join the base directory with manifest base path and fragment relative path
	resolved := filepath.Join(se.baseDir, sanitizedBase, sanitizedRel)
	return resolved
}

func (se *SerializerEngine) validateResolved(resolved string) bool {
	// Ensure the resolved path is within our base directory
	absBase, err := filepath.Abs(se.baseDir)
	if err != nil {
		return false
	}
	absResolved, err := filepath.Abs(resolved)
	if err != nil {
		return false
	}
	return strings.HasPrefix(absResolved, absBase)
}

func (se *SerializerEngine) LoadManifest(data []byte) (*SerializationManifest, error) {
	var manifest SerializationManifest
	if err := json.Unmarshal(data, &manifest); err != nil {
		return nil, fmt.Errorf("invalid manifest: %w", err)
	}
	if manifest.Version == "" || len(manifest.Fragments) == 0 {
		return nil, fmt.Errorf("manifest missing required fields")
	}
	return &manifest, nil
}

func (se *SerializerEngine) ReadFragment(manifest *SerializationManifest, fragment *FragmentRef) ([]byte, error) {
	var result []byte
	err := se.cb.Execute(func() error {
		resolved := se.resolveFragmentPath(manifest, fragment)

		if !se.validateResolved(resolved) {
			return fmt.Errorf("path validation failed for: %s", fragment.Name)
		}

		data, err := os.ReadFile(resolved)
		if err != nil {
			return fmt.Errorf("read error: %w", err)
		}
		result = data
		return nil
	})
	return result, err
}

func (se *SerializerEngine) DeserializeAll(manifestData []byte) (map[string][]byte, error) {
	manifest, err := se.LoadManifest(manifestData)
	if err != nil {
		return nil, err
	}

	results := make(map[string][]byte)
	for i := range manifest.Fragments {
		data, err := se.ReadFragment(manifest, &manifest.Fragments[i])
		if err != nil {
			return nil, fmt.Errorf("fragment %s: %w", manifest.Fragments[i].Name, err)
		}
		results[manifest.Fragments[i].Name] = data
	}
	return results, nil
}
